"using System;\nusing System.Collections.Generic;\nusing System.IO;\nusing System.Linq;\nusing System.Text;\nusing System.Text.Json;\n\nclass Program\n{\n    static readonly JsonSerializerOptions JsonOptions = new()\n    {\n        PropertyNamingPolicy = JsonNamingPolicy.CamelCase\n    };\n\n    static void Main()\n    {\n        using var stdin = Console.OpenStandardInput();\n        using var reader = new StreamReader(stdin, Encoding.UTF8);\n        using var stdout = Console.OpenStandardOutput();\n        using var writer = new StreamWriter(stdout, new UTF8Encoding(false)) { AutoFlush = false };\n        writer.NewLine = \"\\n\";\n        string? line;\n        while ((line = reader.ReadLine()) != null)\n        {\n            if (string.IsNullOrWhiteSpace(line)) continue;\n            var result = Process(line);\n            writer.WriteLine(JsonSerializer.Serialize(result, JsonOptions));\n            writer.Flush();\n        }\n    }\n\n    static Response Process(string line)\n    {\n        using var doc = JsonDocument.Parse(line);\n        var root = doc.RootElement;\n        var fieldsElem = root.GetProperty(\"fields\");\n        var dataElem = root.GetProperty(\"data\");\n\n        var rules = new Dictionary<string, FieldRule>(StringComparer.Ordinal);\n        foreach (var prop in fieldsElem.EnumerateObject())\n        {\n            var r = prop.Value;\n            var rule = new FieldRule\n            {\n                Type = r.GetProperty(\"type\").GetString()!,\n                Required = r.TryGetProperty(\"required\", out var req) && req.ValueKind == JsonValueKind.True\n            };\n            if (r.TryGetProperty(\"min\", out var min) && min.ValueKind == JsonValueKind.Number)\n                rule.Min = min.GetDecimal();\n            if (r.TryGetProperty(\"max\", out var max) && max.ValueKind == JsonValueKind.Number)\n                rule.Max = max.GetDecimal();\n            if (r.TryGetProperty(\"enum\", out var enumElem) && enumElem.ValueKind == JsonValueKind.Array)\n            {\n                var list = new List<string>();\n                foreach (var item in enumElem.EnumerateArray())\n                {\n                    if (item.ValueKind == JsonValueKind.String)\n                        list.Add(item.GetString()!);\n                }\n                rule.Enum = list;\n            }\n            rules[prop.Name] = rule;\n        }\n\n        var data = new Dictionary<string, JsonElement>(StringComparer.Ordinal);\n        foreach (var prop in dataElem.EnumerateObject())\n        {\n            data[prop.Name] = prop.Value;\n        }\n\n        var errors = new List<ErrorItem>();\n\n        foreach (var fieldName in rules.Keys.OrderBy(k => k, StringComparer.Ordinal))\n        {\n            var rule = rules[fieldName];\n            if (!data.TryGetValue(fieldName, out var value))\n            {\n                if (rule.Required)\n                    errors.Add(new ErrorItem(fieldName, \"REQUIRED\"));\n                continue;\n            }\n\n            if (value.ValueKind == JsonValueKind.Null)\n            {\n                errors.Add(new ErrorItem(fieldName, \"TYPE\"));\n                continue;\n            }\n\n            bool typeOk = false;\n            decimal? intValue = null;\n            string? strValue = null;\n\n            switch (rule.Type)\n            {\n                case \"string\":\n                    if (value.ValueKind == JsonValueKind.String)\n                    {\n                        typeOk = true;\n                        strValue = value.GetString()!;\n                    }\n                    break;\n                case \"integer\":\n                    if (value.ValueKind == JsonValueKind.Number && TryGetInteger(value, out var iv))\n                    {\n                        typeOk = true;\n                        intValue = iv;\n                    }\n                    break;\n                case \"boolean\":\n                    if (value.ValueKind == JsonValueKind.True || value.ValueKind == JsonValueKind.False)\n                    {\n                        typeOk = true;\n                    }\n                    break;\n            }\n\n            if (!typeOk)\n            {\n                errors.Add(new ErrorItem(fieldName, \"TYPE\"));\n                continue;\n            }\n\n            if (rule.Type == \"string\" && strValue != null)\n            {\n                int count = CountUnicodeCodePoints(strValue);\n                if (rule.Min.HasValue && count < rule.Min.Value)\n                    errors.Add(new ErrorItem(fieldName, \"MIN\"));\n                if (rule.Max.HasValue && count > rule.Max.Value)\n                    errors.Add(new ErrorItem(fieldName, \"MAX\"));\n                if (rule.Enum != null && !rule.Enum.Contains(strValue, StringComparer.Ordinal))\n                    errors.Add(new ErrorItem(fieldName, \"ENUM\"));\n            }\n            else if (rule.Type == \"integer\" && intValue.HasValue)\n            {\n                if (rule.Min.HasValue && intValue.Value < rule.Min.Value)\n                    errors.Add(new ErrorItem(fieldName, \"MIN\"));\n                if (rule.Max.HasValue && intValue.Value > rule.Max.Value)\n                    errors.Add(new ErrorItem(fieldName, \"MAX\"));\n            }\n        }\n\n        foreach (var dataName in data.Keys.Where(k => !rules.ContainsKey(k)).OrderBy(k => k, StringComparer.Ordinal))\n        {\n            errors.Add(new ErrorItem(dataName, \"UNKNOWN\"));\n        }\n\n        return new Response { Valid = errors.Count == 0, Errors = errors };\n    }\n\n    static bool TryGetInteger(JsonElement e, out decimal value)\n    {\n        value = 0;\n        if (e.ValueKind != JsonValueKind.Number) return false;\n        if (!e.TryGetDecimal(out var dec)) return false;\n        if (dec != decimal.Truncate(dec)) return false;\n        value = dec;\n        return true;\n    }\n\n    static int CountUnicodeCodePoints(string s)\n    {\n        int count = 0;\n        for (int i = 0; i < s.Length; i++)\n        {\n            if (char.IsHighSurrogate(s[i]) && i + 1 < s.Length && char.IsLowSurrogate(s[i + 1]))\n            {\n                i++;\n            }\n            count++;\n        }\n        return count;\n    }\n\n    class FieldRule\n    {\n        public string Type { get; set; } = \"\";\n        public bool Required { get; set; }\n        public decimal? Min { get; set; }\n        public decimal? Max { get; set; }\n        public List<string>? Enum { get; set; }\n    }\n\n    class Response\n    {\n        public bool Valid { get; set; }\n        public List<ErrorItem> Errors { get; set; } = new();\n    }\n\n    class ErrorItem\n    {\n        public string Field { get; init; }\n        public string Code { get; init; }\n        public ErrorItem(string field, string code)\n        {\n            Field = field;\n            Code = code;\n        }\n    }\n}\n"
